# Surah Al-Baqarah (chapter 2) — part 18: ayat 171-180 (IDs 178-187)
SURAH = 2

ENTRIES = {
178: (
"اور ان لوگوں کی جو کفر کیا (ان کی) مثال اس شخص کی ہے جو ڈانٹتا ہو اس کو جو نہ سن سکے مگر آواز اور پکار (یعنی بے سمجھ آواز) — بہرے، گونگے، اندھے — پس وہ سمجھ نہیں رکھتے۔",
"""۱۔ کافروں کی حالت ایک واضح مثال سے بیان کی جا رہی ہے۔
۲۔ ’’وَمَثَلُ الَّذِينَ كَفَرُوا كَمَثَلِ الَّذِي يَنْعِقُ بِمَا لَا يَسْمَعُ‘‘ — ان لوگوں کی جو کفر کیا (ان کی) مثال اس شخص کی ہے جو پکارے اس کو جو سن نہ سکے مگر آواز اور پکار (یعنی بے سمجھ آواز) — یعنی وہ آواز تو سنتے ہیں مگر سمجھ نہیں کرتے۔
۳۔ ’’صُمٌّ بُكْمٌ عُمْيٌ فَهُمْ لَا يَعْقِلُونَ‘‘ — بہرے، گونگے، اندھے — پس وہ سمجھ نہیں رکھتے — یعنی ایمان کے تمام دروازے (سماعت، نطق، بصارت) ان کے لیے بے فائدہ ہیں۔
۴۔ یہاں سوال سمجھ کی کمی کا نہیں بلکہ دل کی بے حسی کا ہے — دلیل موجود ہے مگر قبول کرنے کی آمادگی نہیں۔
۵۔ عملی سبق: دل کو صاف رکھیں؛ مسلسل حق سننے کے باوجود اسے نظرانداز کرنا اندھے، بہرے اور گونگے پن کا نمونہ ہے۔"""
),
179: (
"اے ایمان والو! ان پاک چیزوں میں سے کھاؤ جو ہم نے تمہیں رزق دی ہیں — اور اگر تم اللہ کی عبادت کرتے ہو تو اس کا شکر ادا کرو۔",
"""۱۔ مؤمنوں کو حکم دیا جا رہا ہے: حلال اور طیب رزق کھائیں اور شکر ادا کریں۔
۲۔ ’’كُلُوا مِن طَيِّبَاتِ مَا رَزَقْنَاكُمْ‘‘ — ان پاک چیزوں میں سے کھاؤ جو ہم نے تمہیں رزق دی ہیں — یعنی حلال اور طیب رزق کی طرف رجوع کرو۔
۳۔ ’’وَاشْكُرُوا لِلّٰہِ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ‘‘ — اور اگر تم اللہ کی عبادت کرتے ہو تو اس کا شکر ادا کرو — یعنی کھانے کا شکر یہی ہے کہ اسی کی اطاعت کی جائے۔
۴۔ اللہ کا رزق کھانے کے ساتھ شکر کی عادت ڈالنا ایمان کو زندہ رکھنے کا ذریعہ ہے۔
۵۔ عملی سبق: کھانے سے پہلے بسم اللہ اور کھانے کے بعد الحمد اللہ — یہ سنت مؤمن کی پہچان ہے۔"""
),
180: (
"اس نے تم پر (کھانے کے طور پر) حرام کیا مُردار، خون، سور کا گوشت اور وہ (جانور) جو اللہ کے سوا دوسرے (نام پر) ذکر کر کے ذبح کیا گیا ہو — پھر جو مجبور ہو — نہ کہ سرکشی کرنے والا اور نہ حدوں سے تجاوز کرنے والا — تو اس پر کوئی گناہ نہیں — بے شک اللہ بخشنے والا، نہایت رحم والا ہے۔",
"""۱۔ چار چیزیں کھانے کے طور پر صراحتاً حرام قرار دی گئی ہیں — یہ سب میں واضح اور جامع ہیں۔
۲۔ ’’حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ‘‘ — تم پر (کھانے کے طور پر) حرام کیا مُردار — یعنی بغیر ذبح کے مرا ہوا جانور۔
۳۔ ’’وَالدَّمَ‘‘ — خون — یعنی بہایا ہوا خون (کلکلی)۔
۴۔ ’’وَلَحْمَ الْخِنزِيرِ‘‘ — سور کا گوشت — یہ بھی صراحتاً حرام ہے۔
۵۔ ’’وَمَا أُهِلَّ بِهِ لِغَيْرِ اللّٰہِ‘‘ — اور وہ (جانور) جو اللہ کے سوا دوسرے (نام پر) ذکر کر کے ذبح کیا گیا ہو — یعنی اللہ کے علاوہ کسی اور کے نام پر ذبح شدہ جانور۔
۶۔ ’’فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَلَا إِثْمَ عَلَيْهِ‘‘ — پھر جو مجبور ہو — نہ کہ سرکشی کرنے والا اور نہ حدوں سے تجاوز کرنے والا — تو اس پر کوئی گناہ نہیں — یعنی آخری مجبوری میں ان چیزوں کی اجازت ہے۔
۷۔ ’’إِنَّ اللّٰہَ غَفُورٌ رَّحِيمٌ‘‘ — بے شک اللہ بخشنے والا، نہایت رحم والا ہے — یعنی اللہ بندوں کے ساتھ نرمی کرتا ہے۔
۸۔ عملی سبق: اپنی خوراک میں حلال اور طیب کا خیال رکھیں؛ مجبوری کی حد میں شریعت کی اجازت ہے مگر عمومی حکم واضح ہے۔"""
),
181: (
"بے شک جن لوگوں نے چھپایا وہ چیز جو اللہ نے کتاب میں نازل کی اور اس کے بدلے تھوڑا سا (دنیوی فائدہ) خریدا — یہی لوگ اپنے پیٹ میں آگ کے سوا کچھ نہیں کھاتے — اور اللہ قیامت کے دن ان سے بات نہیں کرے گا اور (نہ) انہیں پاک کرے گا — اور ان کے لیے دردناک عذاب ہے۔",
"""۱۔ اللہ کی نازل کردہ ہدایت چھپانے والوں پر سب سے سخت وعید بیان ہو رہی ہے۔
۲۔ ’’إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنزَلَ اللّٰہُ مِنَ الْكِتَابِ‘‘ — بے شک جن لوگوں نے چھپایا وہ چیز جو اللہ نے کتاب میں نازل کی — یعنی قرآن کی تعلیمات چھپانا۔
۳۔ ’’وَيَشْتَرُونَ بِهِ ثَمَنًا قَلِيلًا‘‘ — اور اس کے بدلے تھوڑا سا (دنیوی فائدہ) خریدا — یعنی دنیوی مفاد کے لیے سچائی کی تجارت۔
۴۔ ’’أُولَٰئِكَ مَا يَأْكُلُونَ فِي بُطُونِهِمْ إِلَّا النَّارَ‘‘ — یہی لوگ اپنے پیٹ میں آگ کے سوا کچھ نہیں کھاتے — یعنی ان کی کمائی آگ بن چکی ہے — ان کا سارا عمل دوزخ کا ایندھن ہے۔
۵۔ ’’وَلَا يُكَلِّمُهُمُ اللّٰہُ يَوْمَ الْقِيَامَۃِ وَلَا يُزَكِّيهِمْ‘‘ — اور اللہ قیامت کے دن ان سے بات نہیں کرے گا اور (نہ) انہیں پاک کرے گا — یعنی اللہ کی طرف سے کوئی تسلی اور بخشش نہیں۔
۶۔ ’’وَلَهُمْ عَذَابٌ أَلِيمٌ‘‘ — اور ان کے لیے دردناک عذاب ہے۔
۷۔ عملی سبق: علمِ دین کو چھپانے یا مروڑ کرنے سے بچیں؛ دنیوی فائدہ کے لیے سچائی کی تجارت کبھی نہ کریں۔"""
),
182: (
"یہی لوگ ہیں جنہوں نے ہدایت کے بدلے گمراہی اور (اللہ کی) بخشش کے بدلے عذاب خریدا — پس وہ دوزخ کی آگ پر کیسے صبر کر سکیں گے؟",
"""۱۔ پچھلی آیت کا نتیجہ بیان ہو رہا ہے — ان کے خسارے کی گہرائی۔
۲۔ ’’أُولَٰئِكَ الَّذِينَ اشْتَرَوُا الضَّلَالَةَ بِالْهُدَىٰ‘‘ — یہی لوگ ہیں جنہوں نے ہدایت کے بدلے گمراہی خریدی — یعنی صریح گھاٹا۔
۳۔ ’’وَالْعَذَابَ بِالْمَغْفِرَةِ‘‘ — اور (اللہ کی) بخشش کے بدلے عذاب خریدا — یعنی بخشش اور عذاب میں سے انہوں نے عذاب کو چنا۔
۴۔ ’’فَمَا أَصْبَرَهُمْ عَلَى النَّارِ‘‘ — پس وہ دوزخ کی آگ پر کیسے صبر کر سکیں گے؟ — یعنی جو لوگ جان بوجھ کر یہ گھاٹا کرتے ہیں ان کا صبر آگ میں لاکھ اچھا ہو تو بھی عذاب برداشت کرنا ناممکن ہوگا۔
۵۔ عملی سبق: گناہ کا ارادہ ہرگز نہ کریں؛ چھوٹے گناہ بھی آہستہ آہستہ بڑے بن جاتے ہیں — اللہ کی بخشش معمولی چیز نہیں۔"""
),
183: (
"یہ اس وجہ سے کہ اللہ نے کتاب (قرآن) نازل کیا حق کے ساتھ — اور بے شک جنہوں نے کتاب میں اختلاف کیا بے شک وہ (اختلاف) دور کی دشمنی ہے۔",
"""۱۔ اللہ کی کتاب کا نزول حق پر قائم ہے؛ اس سے اختلاف کرنے والے بڑے جھگڑے میں مبتلا ہوتے ہیں۔
۲۔ ’’ذَٰلِكَ بِأَنَّ اللّٰہَ نَزَّلَ الْكِتَابَ بِالْحَقِّ‘‘ — یہ اس وجہ سے کہ اللہ نے کتاب (قرآن) نازل کیا حق کے ساتھ — یعنی قرآن ہر قسم کے شک اور اختلاف سے پاک ہے۔
۳۔ ’’وَإِنَّ الَّذِينَ اخْتَلَفُوا فِي الْكِتَابِ لَفِي شِقَاقٍ بَعِيدٍ‘‘ — اور بے شک جنہوں نے کتاب میں اختلاف کیا بے شک وہ (اختلاف) دور کی دشمنی ہے — یعنی قرآن کے متعلق جھگڑا ہر دور میں رہا ہے۔
۴۔ اس آیت سے واضح ہے کہ قرآن میں اختلاف آراء فطری ہے؛ لیکن حق کا معیار قرآن ہی ہے۔
۵۔ عملی سبق: قرآن کے تعلق میں اختلاف آراء کو دشمنی نہ بنائیں؛ علم و دیانت سے سیکھیں اور اتفاق کی طرف رجوع کریں۔"""
),
184: (
"نیکی یہ نہیں کہ اپنے چہرے مشرق یا مغرب کی طرف پھیرو — بلکہ نیکی یہ ہے کہ ایمان لائے اللہ پر، قیامت کے دن پر، فرشتوں پر، کتاب پر اور نبیوں پر — اور مال دے اپنی محبت کی حالت میں رشتہ داروں، یتیموں، مسکینوں، مسافروں (مسافرین)، مانگنے والوں اور غلاموں کی آزادی میں — اور نماز قائم کرے اور زکوٰۃ دے — اور وہ جو اپنے عہد (عہد و اقرار) پورے کریں جب عہد کریں — اور صبر کرنے والے تنگی، تکلیف اور جنگ کے وقت میں — یہی لوگ ہیں جو سچے ہیں اور یہی پرہیزگار ہیں۔",
"""۱۔ یہ آیت نیکی (برّ) کی سب سے جامع تعریف ہے — قرآن کا سب سے جامع حکم۔
۲۔ ’’لَيْسَ الْبِرَّ أَن تُوَلُّوا وُجُوهَكُمْ قِبَلَ الْمَشْرِقِ وَالْمَغْرِب‘‘ — نیکی یہ نہیں کہ اپنے چہرے مشرق یا مغرب کی طرف پھیرو — یعنی صرف قبلے کی طرف منہ کرنے سے نیکی مکمل نہیں ہوتی۔
۳۔ ’’وَلَٰكِنَّ الْبِرَّ مَنْ آمَنَ بِاللّٰہِ وَالْيَوْمِ الْآخِرِ وَالْمَلَائِكَۃِ وَالْكِتَابِ وَالنَّبِيِّينَ‘‘ — بلکہ نیکی یہ ہے کہ ایمان لائے اللہ پر، قیامت کے دن پر، فرشتوں پر، کتاب پر اور نبیوں پر — یعنی ایمانِ بالآخرت، فرشتوں اور کتابوں پر ایمان برّ کا حصہ ہے۔
۴۔ ’’وَآتَى الْمَالَ عَلَىٰ حُبِّهِ‘‘ — اور مال دے اپنی محبت کی حالت میں — یعنی مال کے چاہنے کے باوجود واپس دینا۔
۵۔ ’’ذَوِي الْقُرْبَىٰ وَالْيَتَامَىٰ وَالْمَسَاكِينَ وَابْنَ السَّبِيلِ وَالسَّائِلِينَ وَفِي الرِّقَابِ‘‘ — رشتہ داروں، یتیموں، مسکینوں، مسافروں (مسافرین)، مانگنے والوں اور غلاموں کی آزادی میں — یعنی چھ قسم کے حاجت مند لوگ۔
۶۔ ’’وَأَقَامَ الصَّلَاةَ وَآتَى الزَّكَاةَ‘‘ — اور نماز قائم کرے اور زکوٰۃ دے — یعنی حقوق اللہ اور حقوق الناس دونوں۔
۷۔ ’’وَالْمُوفُونَ بِعَهْدِهِمْ إِذَا عَاهَدُوا‘‘ — اور وہ جو اپنے عہد (عہد و اقرار) پورے کریں جب عہد کریں — یعنی عہد نبھانا عملی نیکی کا حصہ ہے۔
۸۔ ’’وَالصَّابِرِينَ فِي الْبَأْسَاءِ وَالضَّرَّاءِ وَحِينَ الْبَأْسِ‘‘ — اور صبر کرنے والے تنگی، تکلیف اور جنگ کے وقت میں — یعنی صبر ہر مشکل میں۔
۹۔ ’’أُولَٰئِكَ الَّذِينَ صَدَقُوا وَأُولَٰئِكَ هُمُ الْمُتَّقُونَ‘‘ — یہی لوگ ہیں جو سچے ہیں اور یہی پرہیزگار ہیں — یعنی برّ کے معیار پر پورے اترنے والے ہی متقی ہیں۔
۱۰۔ عملی سبق: نیکی کو کسی ایک عمل تک محدود نہ سمجھیں؛ ایمان، مال، نماز، زکوٰۃ، عہد اور صبر سب مل کر نیکی بناتے ہیں۔"""
),
185: (
"اے ایمان والو! تم پر قتل (مقتولین کے بدلہ میں) قصاص (بدلنا) فرض کیا گیا ہے — آزاد کے بدلے آزاد، غلام کے بدلے غلام اور عورت کے بدلے عورت — پس اگر اس کے بھائی کی طرف سے کچھ معاف کر دیا جائے تو پیروی (معروف) کے ساتھ اور ادائیگی (احسان) کے ساتھ — یہ تمہارے رب کی طرف سے تخفیف اور رحمت ہے — پھر جو کوئی اس کے بعد زیادتی کرے تو اس کے لیے دردناک عذاب ہے۔",
"""۱۔ قصاص (قتل کا بدلہ) کا قانون بیان ہو رہا ہے — اسلام عدل اور انسانیت کے توازن پر قائم ہے۔
۲۔ ’’كُتِبَ عَلَيْكُمُ الْقِصَاصُ فِي الْقَتْلَىٰ‘‘ — تم پر قتل (مقتولین کے بدلہ میں) قصاص فرض کیا گیا ہے — یعنی قاتل کو بدلہ ملنا واجب ہے۔
۳۔ ’’الْحُرُّ بِالْحُرِّ وَالْعَبْدُ بِالْعَبْدِ وَالْأُنثَىٰ بِالْأُنثَىٰ‘‘ — آزاد کے بدلے آزاد، غلام کے بدلے غلام اور عورت کے بدلے عورت — یعنی متناسب بدلہ (مساوات)۔
۴۔ ’’فَمَنْ عُفِيَ لَهُ مِنْ أَخِيهِ شَيْءٌ فَاتِّبَاعٌ بِالْمَعْرُوفِ وَأَدَاءٌ إِلَيْهِ بِإِحْسَانٍ‘‘ — پس اگر اس کے بھائی کی طرف سے کچھ معاف کر دیا جائے تو پیروی (معروف) کے ساتھ اور ادائیگی (احسان) کے ساتھ — یعنی اگر ورثاء قصاص معاف کر دیں اور دیت (خون بہا) قبول کریں تو حسن سلوک کے ساتھ وصول کریں۔
۵۔ ’’ذَٰلِكَ تَخْفِيفٌ مِّن رَّبِّكُمْ وَرَحْمَۃٌ‘‘ — یہ تمہارے رب کی طرف سے تخفیف اور رحمت ہے — یعنی اسلام نے قتل کے بدلہ میں درگزر کی راہ بھی کھولی۔
۶۔ ’’فَمَنِ اعْتَدَىٰ بَعْدَ ذَٰلِكَ فَلَهُ عَذَابٌ أَلِيمٌ‘‘ — پھر جو کوئی اس کے بعد زیادتی کرے تو اس کے لیے دردناک عذاب ہے — یعنی معاف کرنے کے بعد دوبارہ زیادتی کا وبال۔
۷۔ عملی سبق: عدل قائم کرو مگر درگزر کا دروازہ بند نہ کرو؛ معاف کرنا بھی مردوں اور بڑوں کی شان ہے۔"""
),
186: (
"اور تمہارے لیے قصاص میں زندگی ہے اے عقل والو! — شاید کہ تم ڈرو (اللہ سے)۔",
"""۱۔ قصاص کا سب سے بڑا فائدہ بیان ہو رہا ہے — معاشرے میں امن کا قیام۔
۲۔ ’’وَلَكُمْ فِي الْقِصَاصِ حَيَاةٌ‘‘ — اور تمہارے لیے قصاص میں زندگی ہے — یعنی قصاص سے معاشرہ امن و سکون پاتا ہے؛ قتل میں کمی آتی ہے۔
۳۔ ’’يَا أُولِي الْأَلْبَابِ‘‘ — اے عقل والو! — یعنی قصاص کی دانائی اہلِ عقل جانتے ہیں۔
۴۔ ’’لَعَلَّكُمْ تَتَّقُونَ‘‘ — شاید کہ تم ڈرو (اللہ سے) — یعنی قصاص کا علم تقویٰ کا ذریعہ ہے۔
۵۔ عملی سبق: جرم کے خاتمے کے لیے عدل ضروری ہے؛ قصاص کا نظام معاشرہ میں امن کی بنیاد ہے۔"""
),
187: (
"تم پر فرض کیا گیا ہے جب تم میں سے کسی کو موت آئے اگر اس نے کچھ مال چھوڑا تو (وصیت کرے) والدین اور قریبی رشتہ داروں کے لیے معروف (طریقے سے) — یہ متقیوں پر حق (واجب) ہے۔",
"""۱۔ موت سے پہلے وصیت کی اہمیت بیان ہو رہی ہے — مال کی تقسیم میں انصاف اور رحمت۔
۲۔ ’’كُتِبَ عَلَيْكُمْ إِذَا حَضَرَ أَحَدَكُمُ الْمَوْتُ إِن تَرَكَ خَيْرًا الْوَصِيَّۃُ‘‘ — تم پر فرض کیا گیا ہے جب تم میں سے کسی کو موت آئے اگر اس نے کچھ مال چھوڑا تو (وصیت کرے) — یعنی مرنے والا اپنی جائداد کے ایک تہائی سے وصیت کر سکتا ہے۔
۳۔ ’’لِلْوَالِدَيْنِ وَالْأَقْرَبِينَ بِالْمَعْرُوفِ‘‘ — والدین اور قریبی رشتہ داروں کے لیے معروف (طریقے سے) — یعنی وراثت سے متعلق رشتہ داروں کو بھی حصہ مل جائے کھولنا۔
۴۔ ’’حَقًّا عَلَى الْمُتَّقِينَ‘‘ — یہ متقیوں پر حق (واجب) ہے — یعنی متقیوں کی ذمہ داری ہے کہ وہ وصیت درست طریقے سے کریں۔
۵۔ بعد میں وراثتِ الٰہی کے احکام نازل ہوئے (سورۂ نساء) جنہوں نے وارثوں کے لازمی حصے مقرر کر دیے؛ اس لیے والدین جیسے وارثوں کے لیے وصیت کی ضرورت نہیں رہی، وصیت اب غیر وارثوں کے لیے تہائی مال تک جائز ہے۔
۶۔ عملی سبق: زندگی میں جائداد کی تقسیم اور وصیت کا منصوبہ بنائیں؛ ورثاء کے درمیان جھگڑے کے سب سے بڑے اسباب میں سے ایک عدمِ وصیت ہے۔"""
),
}
